import{_ as e,o as d,c as a,ag as o}from"./chunks/framework.CrXGS008.js";const b=JSON.parse('{"title":"Ajustes","description":"","frontmatter":{},"headers":[],"relativePath":"es/repair-station/settings.md","filePath":"es/repair-station/settings.md"}'),r={name:"es/repair-station/settings.md"};function s(c,t,n,i,l,h){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="ajustes" tabindex="-1">Ajustes <a class="header-anchor" href="#ajustes" aria-label="Permalink to &quot;Ajustes&quot;">​</a></h1><p>Cada ajuste de la Repair Station se edita en <code>/nay</code>, en la página <strong>Repair Station</strong> (scope <code>nay_repair.config</code>). Los cambios se guardan en la base de datos y se aplican a todos los jugadores a la vez. <code>config.lua</code> contiene valores iniciales opcionales: se aplican hasta que un ajuste se cambia en <code>/nay</code>, y <strong>Restablecer</strong> vuelve a ellos.</p><p>La columna <strong>En /nay</strong> es el nombre que muestra el panel. La clave es el nombre que usan <code>config.lua</code> y la <a href="/es/nay-lib/api">API HTTP</a>.</p><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><table tabindex="0"><thead><tr><th>En /nay</th><th>Clave</th><th>Tipo</th><th>Por defecto</th><th>Descripción</th></tr></thead><tbody><tr><td>Activado</td><td><code>Enabled</code></td><td>sí / no</td><td>sí</td><td>Activa o desactiva todas las estaciones.</td></tr><tr><td>Cuenta de pago</td><td><code>Account</code></td><td><code>cash</code>, <code>bank</code> o <code>cash_then_bank</code></td><td><code>cash_then_bank</code></td><td>De dónde se cobra el precio. <code>cash_then_bank</code> usa el banco cuando no hay suficiente efectivo.</td></tr><tr><td>Descuentos por trabajo</td><td><code>JobDiscounts</code></td><td>lista, hasta 32</td><td>ninguno</td><td>Descuentos para un trabajo a partir de un rango.</td></tr><tr><td>Tiempo de espera (segundos)</td><td><code>CooldownSeconds</code></td><td>segundos, 0 a 3600</td><td>0</td><td>Espera mínima entre dos reparaciones del mismo jugador. 0 lo desactiva.</td></tr></tbody></table><p>Las entradas de <strong>Descuentos por trabajo</strong>:</p><table tabindex="0"><thead><tr><th>En /nay</th><th>Clave</th><th>Tipo</th><th>Descripción</th></tr></thead><tbody><tr><td>Trabajo</td><td><code>Job</code></td><td>texto, 1 a 32 caracteres</td><td>Nombre del trabajo, como en tu framework.</td></tr><tr><td>Rango mínimo</td><td><code>MinGrade</code></td><td>número, 0 a 100</td><td>Rango más bajo que obtiene el descuento.</td></tr><tr><td>Descuento (%)</td><td><code>Percent</code></td><td>número, 1 a 100</td><td>Descuento en porcentaje. 100 hace la reparación gratis.</td></tr></tbody></table><h2 id="servicios" tabindex="-1">Servicios <a class="header-anchor" href="#servicios" aria-label="Permalink to &quot;Servicios&quot;">​</a></h2><table tabindex="0"><thead><tr><th>En /nay</th><th>Clave</th><th>Tipo</th><th>Por defecto</th><th>Descripción</th></tr></thead><tbody><tr><td>Servicios de reparación</td><td><code>Services</code></td><td>lista, 1 a 8</td><td>Quick fix 250 $, Body work 400 $, Full repair 700 $</td><td>Servicios ofrecidos en cada estación.</td></tr><tr><td>Precio según los daños</td><td><code>PriceByDamage</code></td><td>sí / no</td><td>sí</td><td>Ajusta el precio a los daños de las partes reparadas.</td></tr><tr><td>Precio mínimo (%)</td><td><code>MinPricePercent</code></td><td>número, 0 a 100</td><td>20</td><td>Parte más baja del precio del servicio cuando el precio sigue los daños.</td></tr><tr><td>Rechazar vehículos sin daños</td><td><code>RequireDamage</code></td><td>sí / no</td><td>sí</td><td>Rechaza un servicio cuando las partes que repara están intactas.</td></tr><tr><td>Clases de vehículo bloqueadas</td><td><code>BlockedClasses</code></td><td>lista de clases de vehículo</td><td>bicicletas, barcos, helicópteros, aviones, trenes</td><td>Clases de vehículo rechazadas en la estación.</td></tr></tbody></table><p>Las entradas de <strong>Servicios de reparación</strong>:</p><table tabindex="0"><thead><tr><th>En /nay</th><th>Clave</th><th>Tipo</th><th>Descripción</th></tr></thead><tbody><tr><td>Nombre</td><td><code>Label</code></td><td>texto, 1 a 32 caracteres</td><td>Nombre que se muestra en el menú de reparación, el historial y los webhooks.</td></tr><tr><td>Precio</td><td><code>Price</code></td><td>número, 0 a 1000000</td><td>Precio con daños máximos, antes de descuentos y del porcentaje de la estación.</td></tr><tr><td>Duración (segundos)</td><td><code>Seconds</code></td><td>número, 3 a 120</td><td>Lo que dura la reparación.</td></tr><tr><td>Repara el motor</td><td><code>Engine</code></td><td>sí / no</td><td>Incluye el depósito.</td></tr><tr><td>Repara la carrocería</td><td><code>Body</code></td><td>sí / no</td><td>Incluye ventanas, puertas y deformaciones.</td></tr><tr><td>Repara los neumáticos</td><td><code>Tyres</code></td><td>sí / no</td><td>Arregla todos los neumáticos reventados.</td></tr></tbody></table><p>Con <code>PriceByDamage</code> activado, el precio es el precio del servicio multiplicado por el mayor daño de las partes que repara, nunca por debajo de <code>MinPricePercent</code> ni por encima del 100 por ciento. Después se aplican el porcentaje de la estación y el descuento por trabajo. Desactivado, siempre se cobra el precio completo.</p><p>Las entradas de <strong>Clases de vehículo bloqueadas</strong> tienen un solo campo, <strong>Clase</strong> (<code>Class</code>), que se elige por nombre entre las clases de vehículo de GTA.</p><h2 id="stations" tabindex="-1">Estaciones <a class="header-anchor" href="#stations" aria-label="Permalink to &quot;Estaciones {#stations}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>En /nay</th><th>Clave</th><th>Tipo</th><th>Por defecto</th><th>Descripción</th></tr></thead><tbody><tr><td>Estaciones</td><td><code>Stations</code></td><td>lista, hasta 64</td><td>Hayes Autos, Sandy Shores, Paleto Bay</td><td>Las estaciones. Se colocan con el <a href="/es/repair-station/stations">editor de estaciones</a>.</td></tr></tbody></table><p>Las entradas se editan mejor con el <a href="/es/repair-station/stations">editor de estaciones</a>, que rellena estos campos por ti:</p><table tabindex="0"><thead><tr><th>En /nay</th><th>Clave</th><th>Tipo</th><th>Descripción</th></tr></thead><tbody><tr><td>Identificador</td><td><code>Id</code></td><td>texto, 8</td><td>8 caracteres (de 0 a 9, de a a f), dados por el editor. Debe ser único.</td></tr><tr><td>Nombre</td><td><code>Label</code></td><td>texto, hasta 48 caracteres</td><td>Se muestra en el aviso, el historial y los webhooks. Opcional.</td></tr><tr><td>Abierta</td><td><code>Enabled</code></td><td>sí / no</td><td>Cierra una estación sin eliminarla.</td></tr><tr><td>Posición del vehículo</td><td><code>Coords</code></td><td>posición y orientación</td><td>Donde se detienen los vehículos, con la orientación.</td></tr><tr><td>Radio (m)</td><td><code>Radius</code></td><td>metros, 1,5 a 6</td><td>Distancia máxima a la posición para que un vehículo esté en la estación.</td></tr><tr><td>Precio (%)</td><td><code>PricePercent</code></td><td>número, 0 a 1000</td><td>Porcentaje aplicado a cada precio en esta estación. 100 mantiene los precios.</td></tr><tr><td>Modelo del prop</td><td><code>Prop</code></td><td>texto, hasta 64 caracteres</td><td>Prop colocado junto a la estación. Opcional.</td></tr><tr><td>Posición del prop</td><td><code>PropCoords</code></td><td>posición y orientación</td><td>Donde está el prop. Opcional.</td></tr><tr><td>Blip del mapa</td><td><code>Blip</code></td><td>sí / no</td><td>Muestra esta estación en el mapa.</td></tr></tbody></table><h2 id="mecanicos" tabindex="-1">Mecánicos <a class="header-anchor" href="#mecanicos" aria-label="Permalink to &quot;Mecánicos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>En /nay</th><th>Clave</th><th>Tipo</th><th>Por defecto</th><th>Descripción</th></tr></thead><tbody><tr><td>Trabajos de mecánico</td><td><code>MechanicJobs</code></td><td>lista, hasta 16</td><td><code>mechanic</code></td><td>Trabajos que cuentan como mecánicos de servicio.</td></tr><tr><td>Límite de mecánicos en servicio</td><td><code>MaxMechanicsOnDuty</code></td><td>número, 0 a 64</td><td>0</td><td>Las estaciones se cierran mientras haya este número de mecánicos o más de servicio. 0 nunca las cierra.</td></tr></tbody></table><p>Las entradas de <strong>Trabajos de mecánico</strong>:</p><table tabindex="0"><thead><tr><th>En /nay</th><th>Clave</th><th>Tipo</th><th>Descripción</th></tr></thead><tbody><tr><td>Trabajo</td><td><code>Job</code></td><td>texto, 1 a 32 caracteres</td><td>Nombre del trabajo, como en tu framework.</td></tr></tbody></table><h2 id="blips" tabindex="-1">Blips <a class="header-anchor" href="#blips" aria-label="Permalink to &quot;Blips&quot;">​</a></h2><table tabindex="0"><thead><tr><th>En /nay</th><th>Clave</th><th>Tipo</th><th>Por defecto</th><th>Descripción</th></tr></thead><tbody><tr><td>Mostrar blips</td><td><code>ShowBlips</code></td><td>sí / no</td><td>sí</td><td>Muestra en el mapa las estaciones que tienen blip.</td></tr><tr><td>Icono del blip</td><td><code>BlipSprite</code></td><td>icono de blip</td><td>446</td><td>Se elige en una lista visual de iconos. Se puede seguir escribiendo cualquier número para un blip personalizado.</td></tr><tr><td>Color del blip</td><td><code>BlipColor</code></td><td>color de blip</td><td>47</td><td>Se elige en una lista visual de colores.</td></tr><tr><td>Tamaño del blip</td><td><code>BlipScale</code></td><td>0,2 a 2</td><td>0,8</td><td>Tamaño del blip.</td></tr></tbody></table>',23)])])}const u=e(r,[["render",s]]);export{b as __pageData,u as default};
